from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
from pathlib import Path
p=Path('/root/output/result.xlsx')
wb=load_workbook(p, data_only=False, keep_vba=False)
ws=wb['Task']
for row_start, row_end in [(12,17),(19,24),(26,31)]:
    for r in range(row_start, row_end+1):
        for c in range(8,13):
            col = get_column_letter(c)
            ws.cell(r,c).value = f'=INDEX(Data!$H$21:$L$38, MATCH($D{r}, Data!$D$21:$D$38, 0), MATCH({col}$10, Data!$H$4:$L$4, 0))'
for r in range(35,41):
    src_offset = r - 35
    gen_row = 12 + src_offset
    grid_row = 19 + src_offset
    base_row = 26 + src_offset
    for c in range(8,13):
        col = get_column_letter(c)
        ws.cell(r,c).value = f'=({col}{gen_row}-{col}{grid_row})/{col}{base_row}*100'
for r in range(42,48):
    label = ws.cell(r,5).value
    for c in range(8,13):
        col = get_column_letter(c)
        if label == 'Minimum':
            formula = f'=MIN({col}35:{col}40)'
        elif label == 'Maximum':
            formula = f'=MAX({col}35:{col}40)'
        elif label == 'Median':
            formula = f'=MEDIAN({col}35:{col}40)'
        elif label == 'Simple mean':
            formula = f'=AVERAGE({col}35:{col}40)'
        elif label == '25th percentile':
            formula = f'=PERCENTILE({col}35:{col}40, 0.25)'
        elif label == '75th percentile':
            formula = f'=PERCENTILE({col}35:{col}40, 0.75)'
        else:
            raise ValueError(f'Unexpected label row {r}: {label!r}')
        ws.cell(r,c).value = formula
for c in range(8,13):
    col = get_column_letter(c)
    ws.cell(50,c).value = f'=SUMPRODUCT({col}35:{col}40, {col}26:{col}31)/SUM({col}26:{col}31)'
wb.save(p)
print('saved', p, p.stat().st_size)
